// File: preconnect-bug-repro.js
// A minimal Node script to reproduce the false positive in uses-rel-preconnect

const UsesRelPreconnect = require('lighthouse/lighthouse-core/audits/uses-rel-preconnect.js');
const networkRecordsToDevtoolsLog = require('lighthouse/lighthouse-core/test/network-records-to-devtools-log.js');

(async () => {
  // Simulate the main document load
  const mainResource = {
    url: 'https://example.com/',
    parsedURL: {securityOrigin: 'https://example.com'},
    endTime: 1,
  };

  // Simulated requests to the two origins we already preconnected to
  const networkRecords = [
    mainResource,
    {
      url: 'https://www.google-analytics.com/analytics.js',
      initiator: {type: 'script', url: mainResource.url},
      startTime: 2,
      timing: {
        dnsStart: 10,
        dnsEnd: 60,
        connectStart: 61,
        connectEnd: 120,
        receiveHeadersEnd: 130,
      },
    },
    {
      url: 'https://fonts.gstatic.com/s/opensans/v17/mem8YaGs126MiZpBA-U.Fp.ttf',
      initiator: {type: 'script', url: mainResource.url},
      startTime: 3,
      timing: {
        dnsStart: 5,
        dnsEnd: 45,
        connectStart: 46,
        connectEnd: 90,
        receiveHeadersEnd: 95,
      },
    },
  ];

  const artifacts = {
    devtoolsLogs: {
      [UsesRelPreconnect.DEFAULT_PASS]: networkRecordsToDevtoolsLog(networkRecords),
    },
    URL: {finalUrl: mainResource.url},
  };

  const context = {settings: {}, computedCache: new Map()};

  // Run the audit
  const result = await UsesRelPreconnect.audit(artifacts, context);

  console.log('Score:', result.score);
  console.log('Reported Wasted Time (rawValue):', result.rawValue);
  console.log('Details.items (origins reported):');
  console.table(result.details.items.map(item => ({origin: item.url, wastedMs: item.wastedMs})));  
})();
